MILLION = 1_000_000
# pydantic-ai's tool for loading a deferred capability (its tools and instructions appear after)
LOAD_TOOL = "load_capability"
# CapabilityInfo.loads, in pydantic-ai's words: deferred = Capability(defer_loading=True)
DEFERRED, ALWAYS_ON = "deferred", "always-on"


@dataclass
class ToolInfo:
    name: str
    about: str
    """Its description, as the model reads it."""
    params: list[dict[str, str]] = field(default_factory=list)
    """name, type, need ('required' or 'default ...'), about."""


@dataclass
class CapabilityInfo:
    name: str
    """Its id (what the model passes to load_capability), or its class for one without an id."""
    loads: str
    """DEFERRED (defer_loading=True: hidden until the model loads it) or ALWAYS_ON."""
    about: str
    """Its `description`: for a deferred one, all the model sees of it (with its id) before loading."""
    builtin: bool = False
    """Part of pydantic-ai itself, not set up in this repo."""
    instructions: str = ""
    """Its own prompt, added when it is active."""
    tools: list[ToolInfo] = field(default_factory=list)


@dataclass
class AgentInfo:
    name: str
    role: str
    defined_in: str
    model: str
    """The setting as written, eg gateway/anthropic:claude-haiku-5-5."""
    model_name: str
    """The model alone, eg claude-haiku-5-5 (what the chat title shows)."""
    details: list[dict[str, str]] = field(default_factory=list)
    """label / value rows: provider, context window, price, settings, output, retries."""
    instructions: str = ""
    """The agent's own prompt, sent on every request."""
    capabilities: list[CapabilityInfo] = field(default_factory=list)
    tools: list[ToolInfo] = field(default_factory=list)
    """Tools set on the agent itself (outside any capability): always there."""
    loading: list[dict[str, str]] = field(default_factory=list)
    """label / value rows: how the agent's parts reach the model (the app's explanation of the
    setup, in pydantic-ai's parameter names; not text the model gets)."""
    text: str = ""
    """The whole setup as plain text, to copy (eg into a chat with an AI)."""


def _price(model_name: str, provider: str) -> str:
    """List price per 1M tokens: input, cache read, output (genai-prices' bundled data, offline)."""
    try:
        full = calc_price(
            Usage(input_tokens=MILLION, output_tokens=MILLION), model_ref=model_name, provider_id=provider
        )
        cached = calc_price(
            Usage(input_tokens=MILLION, cache_read_tokens=MILLION), model_ref=model_name, provider_id=provider
        )
    except Exception:  # noqa: BLE001  # an unknown model has no list price; show that
        return "unknown (not in genai-prices)"
    prices = (float(full.input_price), float(cached.input_price), float(full.output_price))
    return "${:g} in · ${:g} cache read · ${:g} out, per 1M tokens".format(*prices)


def _type(schema: dict[str, Any]) -> str:
    """A JSON-schema type, short: string, integer, list[string], string | null, one of 'a', 'b'."""
    if "enum" in schema:
        return "one of " + ", ".join(repr(value) for value in schema["enum"])
    if "anyOf" in schema:
        return " | ".join(_type(option) for option in schema["anyOf"])
    kind = str(schema.get("type", "any"))
    if kind == "array":
        return f"list[{_type(schema.get('items') or {})}]"
    return kind


def _tools(toolset: Any) -> list[ToolInfo]:
    """The function tools of a toolset, as the model is told about them."""
    found = []
    for name, tool in (getattr(toolset, "tools", None) or {}).items():
        definition = tool.tool_def
        schema = definition.parameters_json_schema or {}
        required = schema.get("required") or []
        params = [
            {
                "name": param,
                "type": _type(spec),
                "need": "required" if param in required else f"default {spec.get('default')!r}",
                "about": str(spec.get("description", "")),
            }
            for param, spec in (schema.get("properties") or {}).items()
        ]
        found.append(ToolInfo(name=name, about=str(definition.description or "").strip(), params=params))
    return found


def _instructions(sourced: Any) -> str:
    """Instructions as text. One built by a function is called when it takes nothing; one that
    needs the run (its context) can only be named."""
    texts = []
    for item in sourced or []:
        instruction = getattr(item, "instruction", item)
        if callable(instruction):
            try:
                takes_nothing = not inspect.signature(instruction).parameters
                made = instruction() if takes_nothing else None
            except Exception:  # noqa: BLE001  # shown as built at run time rather than breaking the tab
                made = None
            name = getattr(instruction, "__name__", "a function")
            texts.append(made if isinstance(made, str) else f"(built at run time by {name})")
        else:
            texts.append(str(instruction))
    return "\n\n".join(text.strip() for text in texts if text and text.strip())


def _capabilities(agent: Agent[Any, Any]) -> list[CapabilityInfo]:
    """The agent's capabilities in order; pydantic-ai's built-ins (eg ToolSearch) marked as such."""
    found = []
    for capability in getattr(agent.root_capability, "capabilities", None) or []:
        own_id = getattr(capability, "id", None)
        kind = type(capability).__name__
        found.append(
            CapabilityInfo(
                name=str(own_id) if own_id and kind == "Capability" else kind,
                loads=DEFERRED if getattr(capability, "defer_loading", False) else ALWAYS_ON,
                about=str(getattr(capability, "description", "") or ""),
                # the plain Capability class is how this repo's own are made (given an id)
                builtin=kind != "Capability" and type(capability).__module__.startswith("pydantic_ai"),
                instructions=_instructions(getattr(capability, "_instructions", None)),
                tools=_tools(getattr(capability, "_function_toolset", None)),
            )
        )
    return found


def _loading(capabilities: list[CapabilityInfo], own_tools: list[ToolInfo]) -> list[dict[str, str]]:
    """How the agent's parts reach the model, as label / value rows in pydantic-ai's own words
    (its parameter names): the reason an expected tool may go unused. This is the app explaining
    the setup; none of it is text the model gets."""
    deferred = [cap for cap in capabilities if cap.loads == DEFERRED]
    always = [tool.name for tool in own_tools]
    always += [tool.name for cap in capabilities if cap.loads != DEFERRED for tool in cap.tools]
    rows = [
        {"label": "Agent(instructions=...)", "value": "sent on every request"},
        {"label": "tools available from the first request", "value": ", ".join(always) or "none"},
    ]
    if not deferred:
        return [*rows, {"label": "capabilities with defer_loading=True", "value": "none: nothing is loaded later"}]
    hidden = sum(len(cap.tools) for cap in deferred)
    return [
        *rows,
        {
            "label": f"capabilities with defer_loading=True ({len(deferred)})",
            "value": f"the model first gets only each one's `id` and `description`, and the `{LOAD_TOOL}` tool",
        },
        {
            "label": "hidden until loaded",
            "value": f"each deferred capability's `instructions` and `tools` ({hidden} tools in all)",
        },
        {
            "label": "loading",
            "value": " ".join(
                [
                    f"the model calls `{LOAD_TOOL}` with a capability's `id`, deciding from its `description`",
                    "alone; the capability is then active from the next request on, for the rest of the chat",
                ]
            ),
        },
    ]


def _tool_text(tool: ToolInfo, indent: str) -> list[str]:
    lines = [f"{indent}- {tool.name}: {tool.about}"]
    lines += [f"{indent}    {p['name']}: {p['type']} ({p['need']}) {p['about']}".rstrip() for p in tool.params]
    return lines


def _text(info: AgentInfo) -> str:
    """The setup as plain text, to copy."""
    lines = [f"Agent {info.name} ({info.role})", f"model: {info.model}"]
    lines += [f"{row['label']}: {row['value']}" for row in info.details]
    lines += [f"defined in: {info.defined_in}", "", "How it loads (pydantic-ai's parameter names):"]
    lines += [f"- {row['label']}: {row['value']}" for row in info.loading]
    lines += ["", "instructions:", info.instructions or "(none)"]
    if info.tools:
        lines += ["", "tools on the agent itself:"]
        for tool in info.tools:
            lines += _tool_text(tool, "")
    for cap in info.capabilities:
        builtin = ", pydantic-ai built-in" if cap.builtin else ""
        lines += ["", f"Capability {cap.name} ({cap.loads}{builtin}), description: {cap.about or '(none)'}"]
        if cap.instructions:
            lines += ["  instructions:", *[f"    {line}" for line in cap.instructions.splitlines()]]
        for tool in cap.tools:
            lines += _tool_text(tool, "  ")
    return "\n".join(lines)


def activity(messages: Iterable[Any]) -> tuple[list[str], list[dict[str, str]]]:
    """What a chat did with the agent's setup so far, from its message history:
    (ids of the capabilities the model loaded, [{tool, calls}] most called first).

    A load counts once it returned as a success (a refused one, eg an unknown id, is a retry).
    """
    asked: dict[str, str] = {}
    loaded: list[str] = []
    calls: Counter[str] = Counter()
    for message in messages:
        for part in getattr(message, "parts", []):
            if isinstance(part, ToolCallPart):
                if part.tool_name != LOAD_TOOL:
                    calls[part.tool_name] += 1
                    continue
                try:
                    asked[part.tool_call_id] = str(part.args_as_dict().get("id", ""))
                except Exception:  # noqa: BLE001  # arguments the model sent that aren't valid JSON
                    continue
            elif isinstance(part, ToolReturnPart) and part.tool_name == LOAD_TOOL:
                if getattr(part, "outcome", "success") != "success":
                    continue  # refused: sent back to the model to try again
                capability = asked.get(part.tool_call_id, "")
                if capability and capability not in loaded:
                    loaded.append(capability)
    return loaded, [{"tool": tool, "calls": str(count)} for tool, count in calls.most_common()]


def _info(agent: Agent[Any, Any], role: str, defined_in: str) -> AgentInfo:
    model = str(agent.model)
    resolved = infer_model(agent.model)
    provider = resolved.system
    via = " (via the Pydantic AI Gateway)" if model.startswith("gateway/") else ""
    window = resolved.context_window
    output = getattr(agent.output_type, "__name__", str(agent.output_type))
    details = [
        {"label": "provider", "value": f"{provider}{via}"},
        {"label": "context window", "value": f"{tokens_text(window)} tokens" if window else "unknown"},
        {"label": "price", "value": _price(resolved.model_name, provider)},
        {"label": "model settings", "value": str(agent.model_settings or "defaults")},
        {"label": "output", "value": "text" if output == "str" else output},
        {
            "label": "retries",
            "value": f"{agent._max_tool_retries} per tool call, {agent._max_output_retries} for the output",  # noqa: SLF001  # no public getter
        },
    ]
    capabilities = _capabilities(agent)
    own_tools = _tools(getattr(agent, "_function_toolset", None))
    info = AgentInfo(
        name=str(agent.name or "?"),
        role=role,
        defined_in=defined_in,
        model=model,
        model_name=resolved.model_name,
        details=details,
        instructions=_instructions(getattr(agent, "_instructions", None)),
        capabilities=capabilities,
        tools=own_tools,
        loading=_loading(capabilities, own_tools),
    )
    info.text = _text(info)
    return info


